import * as THREE from 'three';

// Shared wave definition. These parameters are used both by the GPU
// (vertex displacement of the ocean) and by the CPU (buoyancy of the surfer),
// so the pelican always sits exactly on the visible surface.

export const WAVES = [
  { dir: new THREE.Vector2(1.0, 0.25).normalize(), amplitude: 0.55, wavelength: 26.0, speed: 0.95 },
  { dir: new THREE.Vector2(1.0, 0.60).normalize(), amplitude: 0.30, wavelength: 14.0, speed: 1.25 },
  { dir: new THREE.Vector2(1.0, -0.40).normalize(), amplitude: 0.16, wavelength: 8.0, speed: 1.70 },
  { dir: new THREE.Vector2(0.5, 1.00).normalize(), amplitude: 0.09, wavelength: 5.2, speed: 2.10 },
];

export function waveHeight(x, z, t) {
  let h = 0;
  for (const w of WAVES) {
    const k = (2 * Math.PI) / w.wavelength;
    const omega = k * w.speed;
    const phase = k * (w.dir.x * x + w.dir.y * z) - omega * t;
    h += w.amplitude * Math.sin(phase);
  }
  return h;
}

export function waveNormal(target, x, z, t) {
  let nx = 0;
  let nz = 0;
  for (const w of WAVES) {
    const k = (2 * Math.PI) / w.wavelength;
    const omega = k * w.speed;
    const phase = k * (w.dir.x * x + w.dir.y * z) - omega * t;
    const c = Math.cos(phase);
    nx += -w.dir.x * k * w.amplitude * c;
    nz += -w.dir.y * k * w.amplitude * c;
  }
  return target.set(nx, 1, nz).normalize();
}

// Generates GLSL with the same waves baked in as constants.
export function waveGLSL() {
  let height = 'float waveHeight(vec2 p, float t) {\n  float h = 0.0;\n';
  let normal = 'vec3 waveNormal(vec2 p, float t) {\n  vec3 n = vec3(0.0, 1.0, 0.0);\n';

  for (const w of WAVES) {
    const k = (2 * Math.PI) / w.wavelength;
    const omega = k * w.speed;
    const dx = w.dir.x;
    const dz = w.dir.y;
    const a = w.amplitude;
    const nx = -dx * k * a;
    const nz = -dz * k * a;

    height += `  { float ph = ${k} * (${dx} * p.x + ${dz} * p.y) - ${omega} * t;\n`;
    height += `    h += ${a} * sin(ph); }\n`;

    normal += `  { float ph = ${k} * (${dx} * p.x + ${dz} * p.y) - ${omega} * t;\n`;
    normal += `    float c = cos(ph);\n`;
    normal += `    n.x += ${nx} * c;\n`;
    normal += `    n.z += ${nz} * c; }\n`;
  }

  height += '  return h;\n}\n';
  normal += '  return normalize(n);\n}\n';
  return height + normal;
}

import * as THREE from 'three';
import { waveGLSL, waveHeight, waveNormal } from './waves.js';

// A large plane whose vertices are displaced on the GPU by a sum of sine
// waves. Lighting/normals are recomputed from the analytic wave normal.
export function createOcean() {
  const uniforms = { uTime: { value: 0 } };

  const geometry = new THREE.PlaneGeometry(400, 400, 400, 400);
  geometry.rotateX(-Math.PI / 2);

  const material = new THREE.MeshStandardMaterial({
    color: 0x1d6fa5,
    roughness: 0.22,
    metalness: 0.05,
  });

  material.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = uniforms.uTime;
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>\nuniform float uTime;\n${waveGLSL()}`
      )
      .replace(
        '#include <beginnormal_vertex>',
        '#include <beginnormal_vertex>\n  objectNormal = waveNormal(position.xz, uTime);'
      )
      .replace(
        '#include <begin_vertex>',
        '#include <begin_vertex>\n  transformed.y += waveHeight(transformed.xz, uTime);'
      );
  };

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.name = 'ocean';

  return {
    mesh,
    waveHeight,
    waveNormal,
    update(t) {
      uniforms.uTime.value = t;
    },
  };
}

import * as THREE from 'three';

// Gradient sky dome with a soft sun glow, plus a few drifting clouds.
export function createSky(sunDirection) {
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      topColor: { value: new THREE.Color(0x1c6fb0) },
      midColor: { value: new THREE.Color(0x77b6d8) },
      bottomColor: { value: new THREE.Color(0xffdcb0) },
      sunDir: { value: sunDirection.clone().normalize() },
      sunColor: { value: new THREE.Color(0xfff1c8) },
    },
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      varying vec3 vDir;
      uniform vec3 topColor;
      uniform vec3 midColor;
      uniform vec3 bottomColor;
      uniform vec3 sunDir;
      uniform vec3 sunColor;
      void main() {
        float h = clamp(vDir.y, -1.0, 1.0);
        vec3 col = mix(bottomColor, midColor, smoothstep(-0.05, 0.28, h));
        col = mix(col, topColor, smoothstep(0.22, 0.85, h));
        float s = max(dot(vDir, normalize(sunDir)), 0.0);
        col += sunColor * pow(s, 6.0) * 0.28;
        col += sunColor * pow(s, 220.0) * 2.0;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });

  const sky = new THREE.Mesh(new THREE.SphereGeometry(900, 48, 24), skyMat);
  sky.frustumCulled = false;

  const root = new THREE.Group();
  root.add(sky);

  // Clouds: clusters of soft spheres drifting slowly across the sky.
  const cloudMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 1.0,
    metalness: 0.0,
    transparent: true,
    opacity: 0.92,
    fog: true,
  });

  const clouds = [];
  const cloudGroup = new THREE.Group();
  root.add(cloudGroup);

  const puff = new THREE.SphereGeometry(1, 16, 12);

  for (let i = 0; i < 8; i++) {
    const cloud = new THREE.Group();
    const puffs = 4 + Math.floor(Math.random() * 4);
    for (let p = 0; p < puffs; p++) {
      const m = new THREE.Mesh(puff, cloudMat);
      const s = 2.5 + Math.random() * 3.5;
      m.scale.set(s * (1 + Math.random() * 0.6), s * 0.7, s);
      m.position.set(
        (Math.random() - 0.5) * 10,
        (Math.random() - 0.5) * 1.5,
        (Math.random() - 0.5) * 5
      );
      cloud.add(m);
    }
    const angle = Math.random() * Math.PI * 2;
    const radius = 90 + Math.random() * 120;
    cloud.position.set(
      Math.cos(angle) * radius,
      34 + Math.random() * 34,
      Math.sin(angle) * radius
    );
    cloud.userData.speed = 0.6 + Math.random() * 1.0;
    clouds.push(cloud);
    cloudGroup.add(cloud);
  }

  function update(dt) {
    for (const cloud of clouds) {
      cloud.position.x += cloud.userData.speed * dt;
      if (cloud.position.x > 260) cloud.position.x = -260;
    }
  }

  return { root, update };
}

import * as THREE from 'three';

function standard(color, extra = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: 0.75,
    metalness: 0.0,
    ...extra,
  });
}

function roundedFeatherShape() {
  const s = new THREE.Shape();
  s.moveTo(0, -0.35);
  s.bezierCurveTo(0.55, 0.0, 0.5, 1.4, 0.15, 2.3);
  s.bezierCurveTo(0.05, 2.55, -0.15, 2.55, -0.3, 2.35);
  s.bezierCurveTo(-0.7, 1.4, -0.75, 0.4, -0.45, -0.25);
  s.quadraticCurveTo(-0.25, -0.45, 0, -0.35);
  return s;
}

function boardShape() {
  const s = new THREE.Shape();
  s.moveTo(-2.05, 0);
  s.bezierCurveTo(-1.8, 0.5, -0.9, 0.62, 0.1, 0.6);
  s.bezierCurveTo(1.0, 0.58, 1.8, 0.4, 2.1, 0);
  s.bezierCurveTo(1.8, -0.4, 1.0, -0.58, 0.1, -0.6);
  s.bezierCurveTo(-0.9, -0.62, -1.8, -0.5, -2.05, 0);
  return s;
}

export function createPelican() {
  const group = new THREE.Group();

  const white = standard(0xf6f2e8, { roughness: 0.85 });
  const beakMat = standard(0xffa22e, { roughness: 0.4 });
  const pouchMat = standard(0xf27a1d, { roughness: 0.5 });
  const legMat = standard(0xf59a2b, { roughness: 0.5 });
  const eyeMat = standard(0x141414, { roughness: 0.25 });
  const boardMat = standard(0xff5a4d, { roughness: 0.3 });
  const stripeMat = standard(0xfff0c4, { roughness: 0.3 });
  const finMat = standard(0xffd24d, { roughness: 0.4 });

  /* ---------------------------------------------------------------- board */
  const boardGeo = new THREE.ExtrudeGeometry(boardShape(), {
    depth: 0.12,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.04,
    bevelSegments: 3,
    steps: 1,
    curveSegments: 24,
  });
  boardGeo.rotateX(-Math.PI / 2);
  boardGeo.translate(0, -0.15, 0);
  const board = new THREE.Mesh(boardGeo, boardMat);
  board.castShadow = true;
  group.add(board);

  const stripe = new THREE.Mesh(
    new THREE.BoxGeometry(3.4, 0.02, 0.2),
    stripeMat
  );
  stripe.position.set(0, -0.01, 0);
  group.add(stripe);

  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.bezierCurveTo(-0.35, -0.15, -0.45, -0.4, -0.2, -0.62);
  finShape.lineTo(0, -0.55);
  finShape.lineTo(0, 0);
  const finGeo = new THREE.ExtrudeGeometry(finShape, {
    depth: 0.04,
    bevelEnabled: true,
    bevelThickness: 0.01,
    bevelSize: 0.01,
    bevelSegments: 1,
    steps: 1,
  });
  finGeo.translate(0, 0, -0.02);
  const fin = new THREE.Mesh(finGeo, finMat);
  fin.position.set(-1.55, 0.0, 0);
  group.add(fin);

  /* ----------------------------------------------------------------- legs */
  for (const side of [-1, 1]) {
    const leg = new THREE.Mesh(
      new THREE.CylinderGeometry(0.07, 0.08, 0.5, 10),
      legMat
    );
    leg.position.set(0.12, 0.25, side * 0.24);
    leg.rotation.z = -0.12;
    group.add(leg);

    const foot = new THREE.Mesh(new THREE.SphereGeometry(1, 14, 10), legMat);
    foot.scale.set(0.3, 0.06, 0.2);
    foot.position.set(0.24, 0.02, side * 0.24);
    group.add(foot);
  }

  /* ----------------------------------------------------------------- body */
  const body = new THREE.Mesh(new THREE.SphereGeometry(1, 40, 28), white);
  body.scale.set(1.15, 0.92, 0.82);
  body.position.set(-0.05, 1.2, 0);
  group.add(body);

  // Tail feathers
  const tail = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 14), white);
  tail.scale.set(0.42, 0.14, 0.5);
  tail.position.set(-1.12, 1.12, 0);
  tail.rotation.z = 0.18;
  group.add(tail);
  for (let i = -2; i <= 2; i++) {
    const feather = new THREE.Mesh(
      new THREE.CylinderGeometry(0.02, 0.06, 0.6, 6),
      white
    );
    feather.position.set(-1.3, 1.1, i * 0.12);
    feather.rotation.z = Math.PI / 2 + 0.25;
    feather.rotation.x = i * 0.14;
    group.add(feather);
  }

  /* ----------------------------------------------------------------- neck */
  const neckCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0.3, 1.55, 0),
    new THREE.Vector3(0.7, 1.95, 0),
    new THREE.Vector3(0.92, 2.3, 0),
    new THREE.Vector3(0.9, 2.6, 0),
  ]);
  const neck = new THREE.Mesh(
    new THREE.TubeGeometry(neckCurve, 28, 0.26, 16, false),
    white
  );
  group.add(neck);

  /* ------------------------------------------------------------------ head */
  const headGroup = new THREE.Group();
  headGroup.position.set(0.9, 2.6, 0);
  group.add(headGroup);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.36, 32, 24), white);
  head.scale.set(1.0, 0.95, 0.92);
  head.position.set(0.0, 0.05, 0);
  headGroup.add(head);

  // Bevelled crest at the back of the head
  const crest = new THREE.Mesh(new THREE.SphereGeometry(0.2, 16, 12), white);
  crest.scale.set(0.8, 0.7, 0.7);
  crest.position.set(-0.26, 0.2, 0);
  headGroup.add(crest);

  // Upper mandible
  const upperGeo = new THREE.ConeGeometry(0.17, 2.05, 14);
  upperGeo.rotateZ(-Math.PI / 2);
  upperGeo.scale(1, 1.05, 0.55);
  const upper = new THREE.Mesh(upperGeo, beakMat);
  upper.position.set(0.95, -0.02, 0);
  upper.rotation.z = -0.09;
  headGroup.add(upper);

  // Pouch
  const pouch = new THREE.Mesh(new THREE.SphereGeometry(1, 28, 20), pouchMat);
  const pouchBaseX = 0.92;
  const pouchBaseY = 0.4;
  const pouchBaseZ = 0.36;
  pouch.scale.set(pouchBaseX, pouchBaseY, pouchBaseZ);
  pouch.position.set(0.9, -0.36, 0);
  headGroup.add(pouch);

  // Eyes
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.065, 16, 12), eyeMat);
    eye.position.set(0.2, 0.12, side * 0.24);
    headGroup.add(eye);

    const ring = new THREE.Mesh(
      new THREE.SphereGeometry(0.1, 16, 12),
      standard(0xffe08a, { roughness: 0.4 })
    );
    ring.scale.set(0.35, 1.0, 1.0);
    ring.position.set(0.19, 0.12, side * 0.245);
    headGroup.add(ring);

    const glint = new THREE.Mesh(
      new THREE.SphereGeometry(0.022, 8, 8),
      new THREE.MeshBasicMaterial({ color: 0xffffff })
    );
    glint.position.set(0.24, 0.15, side * 0.28);
    headGroup.add(glint);
  }

  /* ----------------------------------------------------------------- wings */
  const wingShape = roundedFeatherShape();
  const wingGeo = new THREE.ExtrudeGeometry(wingShape, {
    depth: 0.06,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.03,
    bevelSegments: 2,
    steps: 1,
    curveSegments: 16,
  });
  wingGeo.rotateX(Math.PI / 2); // span (shape +Y) now points +Z, thickness -Y

  const wingGeoLeft = wingGeo.clone();
  wingGeoLeft.scale(1, 1, -1);
  wingGeoLeft.computeVertexNormals();

  const wingMat = standard(0xf1ece0, {
    roughness: 0.85,
    side: THREE.DoubleSide,
  });

  const rightPivot = new THREE.Group();
  rightPivot.position.set(0.0, 1.5, 0.62);
  const rightWing = new THREE.Mesh(wingGeo, wingMat);
  rightPivot.add(rightWing);
  group.add(rightPivot);

  const leftPivot = new THREE.Group();
  leftPivot.position.set(0.0, 1.5, -0.62);
  const leftWing = new THREE.Mesh(wingGeoLeft, wingMat);
  leftPivot.add(leftWing);
  group.add(leftPivot);

  /* --------------------------------------------------------------- animate */
  let elapsed = 0;

  function update(t) {
    elapsed = t;

    const flap = 0.14 + 0.52 * Math.sin(t * 4.1);
    rightPivot.rotation.x = -flap;
    leftPivot.rotation.x = flap;
    rightPivot.rotation.y = 0.06 * Math.sin(t * 4.1 + 0.4);
    leftPivot.rotation.y = -0.06 * Math.sin(t * 4.1 + 0.4);

    // Gentle body bob and head sway
    body.position.y = 1.2 + 0.035 * Math.sin(t * 4.1 + 1.1);
    body.rotation.z = 0.02 * Math.sin(t * 2.2);
    neck.rotation.z = 0.02 * Math.sin(t * 2.2 + 0.5);

    headGroup.position.y = 2.6 + 0.04 * Math.sin(t * 2.0);
    headGroup.rotation.z = 0.05 * Math.sin(t * 2.0 + 0.7);

    // Pouch breathes / wobbles
    const wobble = Math.sin(t * 3.3);
    pouch.scale.set(
      pouchBaseX * (1 + 0.05 * wobble),
      pouchBaseY * (1 + 0.15 * wobble),
      pouchBaseZ * (1 + 0.08 * wobble)
    );
    pouch.position.y = -0.36 - 0.03 * wobble;
  }

  update(0);

  return { group, update, get elapsed() { return elapsed; } };
}

import * as THREE from 'three';

// A pool of recycled water-spray particles rendered as soft additive points.
export function createSpray(count = 900) {
  const positions = new Float32Array(count * 3);
  const alphas = new Float32Array(count);
  const sizes = new Float32Array(count);
  const velocities = new Float32Array(count * 3);
  const lives = new Float32Array(count);
  const maxLives = new Float32Array(count);
  let cursor = 0;

  // Park all particles far below the world until they are emitted.
  for (let i = 0; i < count; i++) {
    positions[i * 3 + 1] = -1000;
    alphas[i] = 0;
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));
  geometry.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));

  const material = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.NormalBlending,
    uniforms: {},
    vertexShader: /* glsl */ `
      attribute float aAlpha;
      attribute float aSize;
      varying float vAlpha;
      void main() {
        vAlpha = aAlpha;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = aSize * (320.0 / max(-mv.z, 0.001));
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: /* glsl */ `
      varying float vAlpha;
      void main() {
        vec2 d = gl_PointCoord - vec2(0.5);
        float r = length(d);
        float a = smoothstep(0.5, 0.08, r) * vAlpha;
        if (a <= 0.001) discard;
        gl_FragColor = vec4(0.96, 0.99, 1.0, a);
      }
    `,
  });

  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;

  const attrPos = geometry.getAttribute('position');
  const attrAlpha = geometry.getAttribute('aAlpha');
  const attrSize = geometry.getAttribute('aSize');

  function spawn(position, velocity, size, life) {
    const i = cursor;
    cursor = (cursor + 1) % count;
    const i3 = i * 3;
    positions[i3] = position.x;
    positions[i3 + 1] = position.y;
    positions[i3 + 2] = position.z;
    velocities[i3] = velocity.x;
    velocities[i3 + 1] = velocity.y;
    velocities[i3 + 2] = velocity.z;
    lives[i] = life;
    maxLives[i] = life;
    sizes[i] = size;
    alphas[i] = 0.9;
  }

  function update(dt) {
    for (let i = 0; i < count; i++) {
      if (lives[i] <= 0) continue;
      const i3 = i * 3;
      lives[i] -= dt;
      if (lives[i] <= 0) {
        alphas[i] = 0;
        positions[i3 + 1] = -1000;
        continue;
      }
      velocities[i3 + 1] -= 7.5 * dt;
      positions[i3] += velocities[i3] * dt;
      positions[i3 + 1] += velocities[i3 + 1] * dt;
      positions[i3 + 2] += velocities[i3 + 2] * dt;
      alphas[i] = Math.min(1, lives[i] / maxLives[i]) * 0.9;
    }
    attrPos.needsUpdate = true;
    attrAlpha.needsUpdate = true;
    attrSize.needsUpdate = true;
  }

  return { points, spawn, update };
}

import * as THREE from 'three';
import { createOcean } from './ocean.js';
import { createSky } from './sky.js';
import { createPelican } from './pelican.js';
import { createSpray } from './spray.js';

/* ------------------------------------------------------------------ setup */
const canvas = document.getElementById('scene');
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: 'high-performance',
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;

const scene = new THREE.Scene();
const FOG_COLOR = new THREE.Color(0xbfdfee);
scene.fog = new THREE.Fog(FOG_COLOR, 45, 195);
scene.background = FOG_COLOR.clone();

const camera = new THREE.PerspectiveCamera(
  52,
  window.innerWidth / window.innerHeight,
  0.1,
  2200
);
camera.position.set(30, 8, 10);

/* ------------------------------------------------------------------ light */
const sunDirection = new THREE.Vector3(0.45, 0.42, 0.78).normalize();

const hemi = new THREE.HemisphereLight(0xd8ecff, 0x14506e, 1.05);
scene.add(hemi);

const sun = new THREE.DirectionalLight(0xfff0d2, 2.4);
sun.position.copy(sunDirection).multiplyScalar(120);
scene.add(sun);

const fill = new THREE.DirectionalLight(0x9fd0ff, 0.5);
fill.position.set(-0.6, 0.4, -0.5).multiplyScalar(80);
scene.add(fill);

scene.add(new THREE.AmbientLight(0x3a5a72, 0.35));

/* ------------------------------------------------------------------ world */
const ocean = createOcean();
scene.add(ocean.mesh);

const sky = createSky(sunDirection);
scene.add(sky.root);

const pelican = createPelican();
const surfer = pelican.group;
scene.add(surfer);

const spray = createSpray(900);
scene.add(spray.points);

// Soft foam disc that slides along the surface beneath the board.
function makeFoamTexture() {
  const size = 256;
  const c = document.createElement('canvas');
  c.width = size;
  c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0.0, 'rgba(255,255,255,0.85)');
  g.addColorStop(0.35, 'rgba(235,250,255,0.45)');
  g.addColorStop(0.7, 'rgba(210,240,255,0.12)');
  g.addColorStop(1.0, 'rgba(200,235,255,0.0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const foam = new THREE.Mesh(
  new THREE.PlaneGeometry(9, 9),
  new THREE.MeshBasicMaterial({
    map: makeFoamTexture(),
    transparent: true,
    depthWrite: false,
    opacity: 0.8,
    color: 0xffffff,
  })
);
foam.rotation.x = -Math.PI / 2;
foam.renderOrder = 1;
scene.add(foam);

/* -------------------------------------------------------------- animation */
const clock = new THREE.Clock();
const PATH_RADIUS = 24;
const ANGULAR_SPEED = 0.2;
const BANK = 0.34;

const forward = new THREE.Vector3();
const waveN = new THREE.Vector3();
const zAxis = new THREE.Vector3();
const yAxis = new THREE.Vector3();
const basis = new THREE.Matrix4();
const lookTarget = new THREE.Vector3(0, 2, 0);
const camGoal = new THREE.Vector3();
const desiredLook = new THREE.Vector3();
const spawnPos = new THREE.Vector3();
const spawnVel = new THREE.Vector3();
const tmp = new THREE.Vector3();

function emitSpray(dt) {
  const rate = 150;
  let n = rate * dt;
  let count = Math.floor(n);
  if (Math.random() < n - count) count++;

  const tail = new THREE.Vector3(-2.0, -0.05, 0).applyMatrix4(surfer.matrixWorld);
  const back = tmp.copy(forward).multiplyScalar(-1);

  for (let i = 0; i < count; i++) {
    const side = Math.random() < 0.5 ? 1 : -1;
    spawnPos.copy(tail);
    spawnPos.x += (Math.random() - 0.5) * 0.4;
    spawnPos.z += (Math.random() - 0.5) * 0.4;
    spawnPos.y += 0.05;

    spawnVel
      .copy(back)
      .multiplyScalar(1.4 + Math.random() * 1.8)
      .addScaledVector(zAxis, side * (0.9 + Math.random() * 1.6))
      .addScaledVector(yAxis, 1.6 + Math.random() * 2.2);
    spawnVel.x += (Math.random() - 0.5) * 0.6;
    spawnVel.z += (Math.random() - 0.5) * 0.6;

    spray.spawn(
      spawnPos,
      spawnVel,
      0.08 + Math.random() * 0.16,
      0.7 + Math.random() * 0.9
    );
  }
}

function animate() {
  requestAnimationFrame(animate);

  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  // Path: a large carving circle on the open water.
  const angle = t * ANGULAR_SPEED;
  const px = Math.cos(angle) * PATH_RADIUS;
  const pz = Math.sin(angle) * PATH_RADIUS;

  forward.set(-Math.sin(angle), 0, Math.cos(angle));

  ocean.waveNormal(waveN, px, pz, t);
  waveN.applyAxisAngle(forward, BANK).normalize();

  const surfaceY = ocean.waveHeight(px, pz, t);

  zAxis.crossVectors(forward, waveN).normalize();
  yAxis.crossVectors(zAxis, forward).normalize();
  basis.makeBasis(forward, yAxis, zAxis);
  surfer.quaternion.setFromRotationMatrix(basis);
  surfer.position.set(px, surfaceY + 0.14, pz);
  surfer.updateMatrixWorld();

  pelican.update(t);
  ocean.update(t);
  sky.update(dt);

  // Foam disc sits just off the water under the board.
  foam.position.set(px, surfaceY + 0.04, pz);
  const foamPulse = 1 + 0.1 * Math.sin(t * 3.0);
  foam.scale.set(foamPulse, foamPulse * 1.35, 1);
  foam.rotation.z = angle + Math.PI / 2;
  foam.material.opacity = 0.55 + 0.15 * Math.sin(t * 2.3);

  emitSpray(dt);
  spray.update(dt);

  // Cinematic follow camera.
  const sway = Math.sin(t * 0.6) * 0.8;
  camGoal
    .copy(surfer.position)
    .addScaledVector(forward, -10.5)
    .addScaledVector(yAxis, 4.6 + Math.sin(t * 0.9) * 0.35)
    .addScaledVector(zAxis, -3.6 + sway);
  camera.position.lerp(camGoal, 1 - Math.exp(-dt * 2.6));

  desiredLook
    .copy(surfer.position)
    .addScaledVector(forward, 3.4)
    .addScaledVector(yAxis, 1.5);
  lookTarget.lerp(desiredLook, 1 - Math.exp(-dt * 3.2));
  camera.lookAt(lookTarget);

  renderer.render(scene, camera);
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

animate();

